import crypto from 'node:crypto';

/**
 * Verifies an ECDSA P-256 signature generated by browser Web Crypto API
 * against a public key stored in JWK format.
 */
export function verifyWebCryptoSignature(
  publicKeyJwk: string | object,
  nonce: string,
  signatureBase64: string
): boolean {
  try {
    const jwk = typeof publicKeyJwk === 'string' ? JSON.parse(publicKeyJwk) : publicKeyJwk;
    const publicKey = crypto.createPublicKey({
      key: jwk,
      format: 'jwk',
    });

    const verify = crypto.createVerify('SHA256');
    verify.update(Buffer.from(nonce, 'utf-8'));
    
    // Web Crypto ECDSA produces IEEE P1363 formatted signatures (r || s, 64 bytes for P-256)
    const isValid = verify.verify(
      {
        key: publicKey,
        dsaEncoding: 'ieee-p1363',
      },
      Buffer.from(signatureBase64, 'base64')
    );

    return isValid;
  } catch (error) {
    console.error('Signature verification error:', error);
    return false;
  }
}

/**
 * Computes canonical SHA-256 fingerprint for a JWK public key.
 */
export function computeFingerprint(publicKeyJwk: string | object): string {
  const jwk = typeof publicKeyJwk === 'string' ? JSON.parse(publicKeyJwk) : publicKeyJwk;
  // Sort keys to produce deterministic canonical string
  const canonical = JSON.stringify({
    crv: jwk.crv,
    kty: jwk.kty,
    x: jwk.x,
    y: jwk.y,
  });
  const hash = crypto.createHash('sha256').update(canonical).digest('hex');
  const pairs = hash.match(/.{1,2}/g)?.slice(0, 10).join(':') || hash.slice(0, 20);
  return `SHA256:${pairs}`;
}
